package android.content;import android.app.UiModeManager;import android.view.accessibility.AccessibilityManager;import android.content.res.Resources;import android.content.res.AssetManager;import java.util.ArrayList;import java.util.List;import java.util.LinkedHashMap;import java.util.Map;import java.util.concurrent.Executor;import dev.mixer.android.OwnerHostProbe;
public class Context {public final Resources resources=new Resources();public final AssetManager assets=new AssetManager();public final ContentResolver resolver=new ContentResolver();public final Map<Class<?>,Object> services=new LinkedHashMap<>();public final List<ComponentCallbacks> componentCallbacks=new ArrayList<>();public int componentAdds,componentRemoves;public Context(){services.put(UiModeManager.class,new UiModeManager());services.put(AccessibilityManager.class,new AccessibilityManager());services.put(ClipboardManager.class,new ClipboardManager());}public Resources getResources(){OwnerHostProbe.hit("Context.getResources","entry",this);Resources value=resources;OwnerHostProbe.hit("Context.getResources","beforeReturn",this);return value;}public AssetManager getAssets(){return assets;}public ContentResolver getContentResolver(){return resolver;}public <T>T getSystemService(Class<T> type){return type.cast(services.get(type));}public Executor getMainExecutor(){return Runnable::run;}public void registerComponentCallbacks(ComponentCallbacks callback){OwnerHostProbe.hit("Context.registerComponentCallbacks","entry",this);componentAdds++;componentCallbacks.add(callback);OwnerHostProbe.hit("Context.registerComponentCallbacks","beforeReturn",this);}public void unregisterComponentCallbacks(ComponentCallbacks callback){OwnerHostProbe.hit("Context.unregisterComponentCallbacks","entry",this);componentRemoves++;componentCallbacks.removeIf(item->item==callback);OwnerHostProbe.hit("Context.unregisterComponentCallbacks","beforeReturn",this);}public void hostConfigurationChanged(){for(ComponentCallbacks callback:List.copyOf(componentCallbacks))callback.onConfigurationChanged(resources.configuration);}}
